local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "azeroth", {
	title = "Azeroth",
	sections = {
		{
			title = "Résumé",
			text = [=[Azeroth est le monde. Ses mers portent les continents des {link:eastern-kingdoms}Royaumes de l'est{/link}, de {link:kalimdor}Kalimdor{/link} et du Norfendre gelé, ainsi que d'innombrables îles. Jungles, déserts, forêts et champs de glace s'y côtoient, et sur toutes les terres les ruines des âges anciens reposent sous les villes des nouveaux. C'est un monde de nombreux peuples et d'une très longue mémoire. Encore et encore, des puissances qui le convoitent l'ont fait saigner, et encore et encore il a tenu bon.]=],
		},
		{
			title = "Origines",
			text = [=[Les histoires les plus anciennes disent qu'Azeroth fut façonné par les titans, des êtres semblables à des dieux qui voyageaient parmi les étoiles pour apporter l'ordre aux mondes qu'ils trouvaient. Quand ils vinrent sur Azeroth, il était gouverné par des élémentaires déchaînés et par d'anciens maux qui s'étaient agrippés au monde. Les chroniques nomment ces maux les Dieux très anciens. Les titans brisèrent le pouvoir des uns et des autres. Ils enfermèrent les seigneurs élémentaires dans un royaume séparé du monde, et ils emprisonnèrent les Dieux très anciens au plus profond de la terre, car on ne pouvait les tuer sans blesser le monde lui-même. Puis les titans façonnèrent la terre. Leurs serviteurs élevèrent les montagnes, creusèrent les vallées et remplirent les mers. Les terrestres, des êtres de pierre vivante, furent chargés de veiller sur les profondeurs du monde. Parmi les dragons, les titans en choisirent cinq et donnèrent à chacun une part de leur pouvoir. Ils devinrent les Aspects, chargés de garder Azeroth quand ses créateurs seraient partis. Puis les titans s'en allèrent, et le monde fut laissé à ses propres peuples.]=],
		},
		{
			title = "Les âges du monde",
			text = [=[• {b}L'empire kaldorei.{/b} Au cœur d'un unique grand continent se trouvait le {link:well-of-eternity}puits d'Éternité{/link}. Sur ses rives, les {link:night-elves}elfes de la nuit{/link} élevèrent un empire de merveilles sous le règne de la {link:queen-azshara}reine Azshara{/link}.
• {b}La guerre des Anciens.{/b} La magie imprudente des Bien-nés attira le regard de la {link:burning-legion}Légion ardente{/link}. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, les elfes de la nuit combattirent pour la survie du monde, et la destruction du Puits provoqua la {link:great-sundering}Grande Fracture{/link}. L'unique continent fut brisé en plusieurs.
• {b}Les jeunes races.{/b} Dans les âges qui suivirent, les empires trolls déclinèrent et les {link:dwarves}nains{/link} s'éveillèrent sous les montagnes. Les {link:high-elves}hauts-elfes{/link} fondèrent {link:quel-thalas}Quel'Thalas{/link}, et les tribus {link:humans}humaines{/link} s'unirent sous le nom d'{link:arathor}Arathor{/link} pour livrer les {link:troll-wars}guerres des Trolls{/link}.
• {b}L'âge de la {link:horde}Horde{/link}.{/b} Quand la {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit, les {link:orcs}orcs{/link} d'un autre monde déferlèrent sur Azeroth. La {link:first-war}Première Guerre{/link}, la {link:second-war}Deuxième Guerre{/link} et la {link:third-war}Troisième Guerre{/link} suivirent, chacune plus terrible que la précédente.]=],
		},
		{
			title = "Un nom partagé",
			text = [=[Le nom d'Azeroth appartint jadis aussi à un royaume humain. Les exilés arathis qui s'installèrent dans les forêts du sud appelèrent leur nouveau royaume Azeroth, et sa capitale était {link:stormwind-city}Stormwind{/link}. Avec le temps, le royaume prit le nom de sa cité, et c'est aujourd'hui le {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Les vieux soldats de la {link:first-war}Première Guerre{/link} parlent encore parfois d'« Azeroth » en ne désignant que le royaume qu'ils ont perdu.]=],
		},
		{
			title = "De nos jours",
			text = [=[La {link:third-war}Troisième Guerre{/link} prit fin avec la chute d'{link:archimonde}Archimonde{/link} au pied de {link:nordrassil}Nordrassil{/link}, mais elle n'apporta pas la paix. Le {link:scourge}Fléau{/link} tient le nord de {link:lordaeron}Lordaeron{/link}. Des serviteurs de la {link:burning-legion}Légion ardente{/link} hantent encore les forêts de {link:kalimdor}Kalimdor{/link}. L'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link}, qui combattirent côte à côte sur le mont Hyjal, s'observent désormais avec méfiance à travers les {link:the-barrens}Tarides{/link} et les bois d'{link:ashenvale}Orneval{/link}. Sous {link:blackrock-mountain}le mont Blackrock{/link}, les {link:dark-iron-dwarves}nains Sombrefer{/link} servent un seigneur de feu vivant. Azeroth a survécu à toutes les guerres livrées jusqu'ici sur son sol. Aucun chroniqueur n'oserait dire qu'il ne peut tomber.]=],
		},
	},
})

Translate("frFR", "eastern-kingdoms", {
	title = "Royaumes de l'est",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Royaumes de l'est s'étendent des pics gelés d'{link:alterac-mountains}Alterac{/link} jusqu'aux jungles de {link:stranglethorn-vale}Strangleronce{/link}. Ils sont la patrie de l'{link:humans}humanité{/link}, des {link:dwarves}nains{/link} et des {link:gnomes}gnomes{/link}, ainsi que des {link:high-elves}hauts-elfes{/link} de {link:quel-thalas}Quel'Thalas{/link}. Ici se dressaient les grands royaumes humains d'autrefois, et ici la {link:horde}Horde{/link} mena sa première guerre contre {link:azeroth}Azeroth{/link}. Ces terres portent les cicatrices de toutes les guerres depuis. Des royaumes jadis fiers gisent en ruine, et le nord est devenu une terre des morts.]=],
		},
		{
			title = "Origines",
			text = [=[Avant la {link:great-sundering}Grande Fracture{/link}, ces terres étaient les confins orientaux d'un unique continent. Quand le {link:well-of-eternity}puits d'Éternité{/link} fut détruit, les mers s'engouffrèrent et les arrachèrent. Ce qui restait était une terre déjà ancienne. Les titans y avaient laissé leurs œuvres, dont {link:uldaman}la chambre forte d'Uldaman{/link} dans les pierreuses {link:badlands}Terres ingrates{/link}. Leurs serviteurs terrestres dormaient dans ses salles. Au fil de longs âges, les terrestres changèrent. Leur chair s'amollit et leur vie devint brève, et d'eux vinrent les nains de Khaz Modan. Un autre peuple forgé par les titans, dit-on, donna naissance aux gnomes. Les trolls étaient plus anciens encore sur ces terres. Les Amani régnaient sur les forêts du nord, et les Gurubashi tenaient les jungles du sud.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La venue des elfes.{/b} Exilés de {link:kalimdor}Kalimdor{/link}, les Bien-nés traversèrent la mer et fondèrent {link:quel-thalas}Quel'Thalas{/link} dans les forêts du nord, sur des terres que les Amani revendiquaient comme les leurs.
• {b}Arathor.{/b} Les tribus humaines du nord furent unies par {link:thoradin}Thoradin{/link}, qui éleva la cité de {link:stromgarde-keep}Strom{/link}. Avec les elfes, ses armées brisèrent les Amani lors des {link:troll-wars}guerres des Trolls{/link}. En retour, les elfes enseignèrent aux humains les voies de la magie {link:arathor}arathie{/link}, et Dalaran fut plus tard fondée par les mages de cette lignée.
• {b}Les sept royaumes.{/b} Avec le temps, Arathor se divisa. Les royaumes de {link:lordaeron}Lordaeron{/link}, de {link:gilneas}Gilneas{/link}, de {link:kul-tiras}Kul Tiras{/link}, d'{link:alterac-mountains}Alterac{/link}, de {link:dalaran}Dalaran{/link} et de Stromgarde s'élevèrent au nord. Au sud, des exilés arathis fondèrent le royaume qui devint le {link:kingdom-of-stormwind}royaume de Stormwind{/link}.
• {b}Les Trois Marteaux.{/b} Sous les montagnes, les nains d'{link:kingdom-of-ironforge}Ironforge{/link} se divisèrent en clans Bronzebeard, Wildhammer et {link:dark-iron-dwarves}Sombrefer{/link}. Leur guerre finit dans le feu. Le thane-sorcier sombrefer {link:ruins-of-thaurissan}Thaurissan{/link} invoqua Ragnaros, seigneur du feu, et l'invocation fit surgir {link:blackrock-mountain}le mont Blackrock{/link} et brûla les terres alentour.
• {b}Les guerres de la {link:horde}Horde{/link}.{/b} La {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit au sud. {link:stormwind-city}Stormwind{/link} tomba lors de la {link:first-war}Première Guerre{/link}. L'{link:alliance}Alliance{/link} de Lordaeron repoussa la Horde lors de la {link:second-war}Deuxième Guerre{/link}. Puis vinrent la peste de la non-mort, l'{link:culling-of-stratholme}Épuration de Stratholme{/link} et la {link:fall-of-lordaeron}chute de Lordaeron{/link}.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:stormwind-city}Stormwind{/link} s'est relevée, bien que son roi ait disparu et que son régent, {link:bolvar-fordragon}Bolvar Fordragon{/link}, tienne un royaume à bout de forces. {link:magni-bronzebeard}Magni Bronzebeard{/link} règne à {link:ironforge}Ironforge{/link}, qui abrite aussi les gnomes, car {link:gnomeregan}Gnomeregan{/link} a été perdue par sa propre ruine. Au nord du {link:thandol-span}Viaduc de Thandol{/link}, le grand royaume de {link:lordaeron}Lordaeron{/link} n'est plus. Le {link:scourge}Fléau{/link} tient les {link:eastern-plaguelands}Maleterres{/link}. Les fanatiques de la {link:scarlet-crusade}Croisade écarlate{/link} le combattent par le feu comme par le soupçon. Dans les ruines de l'ancienne capitale, les {link:forsaken}Réprouvés{/link} se sont fait un foyer sous la terre. Dans {link:blackrock-mountain}le mont Blackrock{/link}, {link:dark-iron-dwarves}Sombrefer{/link} et orcs se font la guerre. Et au sud, la {link:dark-portal}Porte des Ténèbres{/link} se dresse, silencieuse, dans les {link:blasted-lands}Terres foudroyées{/link}.]=],
		},
	},
})

Translate("frFR", "kalimdor", {
	title = "Kalimdor",
	sections = {
		{
			title = "Résumé",
			text = [=[Kalimdor s'étend de l'autre côté de la mer, à l'ouest des {link:eastern-kingdoms}Royaumes de l'est{/link}. C'est une terre de vieilles forêts et de canyons rouges, de grandes plaines et de déserts brûlants. C'est la patrie des {link:night-elves}elfes de la nuit{/link} et des {link:tauren}taurens{/link}, et le cœur ancien du monde. Le Kalimdor d'aujourd'hui n'est que ce qui survécut à la {link:great-sundering}Grande Fracture{/link}. Avant ce cataclysme, un unique continent portait presque toutes les terres d'{link:azeroth}Azeroth{/link}, et le lac en son centre était le {link:well-of-eternity}puits d'Éternité{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Les plus anciens peuples de Kalimdor étaient les trolls, dont les empires s'étendaient loin sur le continent primordial. Une tribu de trolls qui s'installa au bord du Puits fut changée par son pouvoir au fil de nombreuses générations. Ils devinrent les elfes de la nuit, qui nommèrent la terre Kalimdor. Au bord du Puits, ils bâtirent les cités de l'empire {link:night-elves}kaldorei{/link} sous le règne de la {link:queen-azshara}reine Azshara{/link}. Leur quête de la {link:arcane-magic}magie arcanique{/link} attira la {link:burning-legion}Légion ardente{/link} dans le monde. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, le Puits fut détruit, et le continent vola en éclats. Les mers se déversèrent dans la blessure, et le Maelström y tourbillonne depuis. Sur les pentes du mont Hyjal, les survivants plantèrent {link:nordrassil}Nordrassil{/link}, et pendant dix mille ans les elfes de la nuit montèrent une garde secrète sur leurs forêts.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La longue veille.{/b} Sous {link:malfurion-stormrage}Malfurion Stormrage{/link} et {link:tyrande-whisperwind}Tyrande Whisperwind{/link}, les elfes de la nuit renoncèrent à la magie arcanique. Les druides dormaient dans le {link:emerald-dream}Rêve d'émeraude{/link}, et les {link:sentinels}Sentinelles{/link} gardaient seules les forêts.
• {b}Les peuples des terres sauvages.{/b} Les taurens parcouraient les plaines. Ils furent harcelés pendant des générations par les {link:centaurs}centaures{/link} du sud, les {link:quilboar}hurans{/link} des {link:the-barrens}Tarides{/link}, les {link:harpies}harpies{/link} des falaises et les {link:furbolgs}furbolgs{/link} des forêts.
• {b}La Troisième Guerre.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, une nouvelle {link:horde}Horde{/link} menée par {link:thrall}Thrall{/link} traversa la mer, tout comme les humains de {link:jaina-proudmoore}Jaina Proudmoore{/link}. La {link:burning-legion}Légion ardente{/link} les suivit. {link:orcs}Orcs{/link}, humains et elfes de la nuit, jadis étrangers et ennemis, combattirent côte à côte lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, et c'est là qu'{link:archimonde}Archimonde{/link} fut détruit.]=],
		},
		{
			title = "De nos jours",
			text = [=[Kalimdor n'est plus une terre cachée. Les elfes de la nuit ont planté un nouvel arbre, {link:teldrassil}Teldrassil{/link}, et sa cité de {link:darnassus}Darnassus{/link} contemple la mer du nord. Les orcs ont fondé {link:durotar}Durotar{/link} et la cité d'{link:orgrimmar}Orgrimmar{/link}, et les taurens de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} ont fait de {link:thunder-bluff}Thunder Bluff{/link} leur foyer en {link:mulgore}Mulgore{/link}. Les {link:darkspear-trolls}trolls Darkspear{/link} vivent aux côtés des orcs. {link:jaina-proudmoore}Jaina Proudmoore{/link} tient {link:theramore-isle}Theramore{/link} dans le {link:dustwallow-marsh}marécage d'Âprefange{/link}. Pourtant, la paix d'Hyjal s'effiloche. Les bûcherons orcs abattent les arbres d'{link:ashenvale}Orneval{/link}, et les {link:sentinels}Sentinelles{/link} répondent par des flèches. Les gobelins du {link:steamwheedle-cartel}Cartel Gentepression{/link} et de la {link:venture-company}KapitalRisk{/link} commercent et pillent le long des côtes. Les forêts de {link:felwood}Gangrebois{/link} portent encore la souillure de la Légion, et des mystères plus anciens dorment dans les déserts du sud.]=],
		},
	},
})

Translate("frFR", "war-of-the-ancients", {
	title = "Guerre des Anciens",
	sections = {
		{
			title = "Résumé",
			text = [=[La guerre des Anciens fut la première invasion d'{link:azeroth}Azeroth{/link} par la {link:burning-legion}Légion ardente{/link}. Elle fut livrée quelque dix mille ans avant l'ouverture de la {link:dark-portal}Porte des Ténèbres{/link}, et elle mit fin à l'empire {link:night-elves}kaldorei{/link}. Sa dernière heure amena la {link:great-sundering}Grande Fracture{/link}, qui brisa le monde.]=],
		},
		{
			title = "Origines",
			text = [=[Les Bien-nés de la cour elfique puisaient toujours plus profondément dans le pouvoir du {link:well-of-eternity}puits d'Éternité{/link}. Leur magie fut ressentie au-delà du monde par {link:sargeras}Sargeras{/link}, le titan déchu qui mène la {link:burning-legion}Légion ardente{/link}. Il murmura à la {link:queen-azshara}reine Azshara{/link}, et elle le crut. {link:azshara}Azshara{/link} et ses Bien-nés œuvrèrent à ouvrir un portail dans le Puits, afin que Sargeras et ses démons puissent entrer dans {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[Les premiers démons passèrent, menés par {link:archimonde}Archimonde{/link} et {link:mannoroth}Mannoroth{/link}, et ils massacrèrent les elfes de la nuit qui se dressaient sur leur chemin. Une résistance se forma contre eux et contre la reine. Elle était menée par {link:malfurion-stormrage}Malfurion Stormrage{/link}, un jeune élève du demi-dieu {link:cenarius}Cenarius{/link}, avec la prêtresse {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et le frère jumeau de Malfurion, {link:illidan-stormrage}Illidan Stormrage{/link}. Les demi-dieux des terres sauvages et les vols draconiques se joignirent au combat. La guerre était presque perdue quand le Gardien de la Terre des dragons trahit les siens. C'était l'Aspect qui allait devenir {link:deathwing}Aile-de-mort{/link}. À la fin, les défenseurs atteignirent le palais des Bien-nés et brisèrent leurs sorts au moment où {link:sargeras}Sargeras{/link} tentait de passer. Le portail s'effondra, et le puits d'Éternité se déchira lui-même.]=],
		},
		{
			title = "Importance",
			text = [=[La guerre apprit aux elfes de la nuit que la magie arcanique avait failli condamner le monde. Ils y renoncèrent, se tournèrent vers le druidisme et le culte d'Elune, et commencèrent leur longue veille. Elle fit aussi d'{link:illidan-stormrage}Illidan{/link} un traître aux yeux de son peuple, car il avait travaillé en secret avec les Bien-nés, et par la suite il créa un nouveau Puits au sommet du mont Hyjal.]=],
		},
	},
})

Translate("frFR", "great-sundering", {
	title = "Grande Fracture",
	aliases = { "Fracture" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Grande Fracture fut le cataclysme qui mit fin à la {link:war-of-the-ancients}guerre des Anciens{/link}. Quand le {link:well-of-eternity}puits d'Éternité{/link} s'effondra, l'unique continent du monde ancien vola en éclats, et les mers s'engouffrèrent pour combler la blessure. Le visage d'{link:azeroth}Azeroth{/link} en fut changé à jamais.]=],
		},
		{
			title = "Histoire",
			text = [=[Le portail des Bien-nés fut défait à la dernière heure de la guerre. Le Puits, nourri de plus de pouvoir qu'il n'en pouvait contenir, implosa. L'explosion arracha le cœur du continent. La plus grande partie de l'empire {link:night-elves}kaldorei{/link}, avec sa resplendissante capitale de Zin-Azshari, fut engloutie par la mer. La {link:queen-azshara}reine Azshara{/link} et nombre de ses Bien-nés furent entraînés sous les flots. Là où se trouvait le Puits, les eaux se mirent à tourner, et la grande tempête appelée le Maelström naquit. Elle n'a jamais cessé.]=],
		},
		{
			title = "Le monde d'après",
			text = [=[Seuls des fragments de l'ancien continent restèrent au-dessus des eaux. Les plus grands devinrent {link:kalimdor}Kalimdor{/link} à l'ouest et les {link:eastern-kingdoms}Royaumes de l'est{/link} à l'est, et la terre gelée du Norfendre se trouvait au nord. Les elfes de la nuit survivants se rassemblèrent sur les pentes du mont Hyjal. Là, ils découvrirent qu'{link:illidan-stormrage}Illidan Stormrage{/link} avait emporté des fioles de l'eau du Puits et les avait versées dans un lac de montagne, créant un second Puits. Pour le garder, les Aspects plantèrent {link:nordrassil}Nordrassil{/link} au-dessus de ses eaux.]=],
		},
		{
			title = "Importance",
			text = [=[Pour les elfes de la nuit, la Fracture fut la preuve du prix de la {link:arcane-magic}magie arcanique{/link}. Pour le monde, elle signifia dix mille ans de séparation. Les peuples de l'est et de l'ouest s'oublièrent jusqu'à ce que la {link:third-war}Troisième Guerre{/link} les réunisse. Les {link:naga}nagas{/link} qui hantent aujourd'hui les côtes seraient les Bien-nés noyés, changés au point d'être méconnaissables.]=],
		},
	},
})

Translate("frFR", "troll-wars", {
	title = "Guerres des Trolls",
	sections = {
		{
			title = "Résumé",
			text = [=[Les guerres des {link:trolls}Trolls{/link} opposèrent les trolls amani aux jeunes royaumes des humains et des {link:high-elves}hauts-elfes{/link}, quelque deux mille huit cents ans avant l'ouverture de la {link:dark-portal}Porte des Ténèbres{/link}. D'elles naquirent l'alliance des elfes et des humains, et les premiers mages humains.]=],
		},
		{
			title = "Origines",
			text = [=[Les Bien-nés exilés de {link:kalimdor}Kalimdor{/link} fondèrent {link:quel-thalas}Quel'Thalas{/link} dans les forêts du nord des {link:eastern-kingdoms}Royaumes de l'est{/link}. Ces forêts avaient appartenu aux Amani, et les trolls ne pardonnèrent jamais ce vol. Ils firent la guerre aux elfes pendant des milliers d'années. Enfin, ils rassemblèrent une grande armée, peut-être rejointe par leurs cousins gurubashi, et partirent détruire Quel'Thalas tout entière.]=],
		},
		{
			title = "Histoire",
			text = [=[À la même époque, {link:thoradin}Thoradin{/link} de la tribu arathie avait uni les tribus humaines du nord en une nation, {link:arathor}Arathor{/link}, avec pour capitale {link:stromgarde-keep}Strom{/link}. Les elfes de {link:quel-thalas}Quel'Thalas{/link} lui envoyèrent des émissaires en désespoir de cause. Thoradin accepta de les aider si les elfes enseignaient la magie à son peuple. Les elfes choisirent cent humains doués pour cet art et ne leur enseignèrent que le nécessaire. Les armées alliées rencontrèrent l'armée amani au sud des montagnes d'{link:alterac-mountains}Alterac{/link}. Les mages humains et les magistères elfes firent pleuvoir le feu sur les trolls, et les flammes consumèrent les blessures que les trolls peuvent d'ordinaire guérir. Les Amani se débandèrent et s'enfuirent, et leur empire ne s'en remit jamais.]=],
		},
		{
			title = "Importance",
			text = [=[En signe de gratitude, les elfes de {link:quel-thalas}Quel'Thalas{/link} jurèrent un serment d'amitié à la lignée de {link:thoradin}Thoradin{/link}. Ce serment allait les entraîner dans la {link:second-war}Deuxième Guerre{/link}. La magie enseignée à l'humanité se répandit bien au-delà des cent premiers. Elle donna naissance à {link:dalaran}Dalaran{/link} et au {link:kirin-tor}Kirin Tor{/link}, et elle attira de nouveau l'attention de la {link:burning-legion}Légion ardente{/link}.]=],
		},
	},
})

Translate("frFR", "first-war", {
	title = "Première Guerre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Première Guerre fut l'invasion du royaume humain d'{link:azeroth}Azeroth{/link} par la {link:horde}Horde{/link} orque. Elle commença quand la {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit dans le Noir Marécage, et elle s'acheva avec la chute de {link:stormwind-city}Stormwind{/link}. Ce fut la première guerre entre orcs et humains, et le début de l'âge qui a façonné le monde depuis.]=],
		},
		{
			title = "Origines",
			text = [=[Sur leur monde de Draenor, les {link:orcs}orcs{/link} avaient été corrompus par le seigneur démon {link:kil-jaeden}Kil'jaeden{/link} par l'intermédiaire du démoniste {link:gul-dan}Gul'dan{/link} et de son {link:shadow-council}Conseil des ombres{/link}. Leur patrie se mourait. Sur {link:azeroth}Azeroth{/link}, {link:medivh}Medivh{/link}, le Gardien de {link:tirisfal-glades}Tirisfal{/link}, était depuis longtemps possédé par l'esprit de {link:sargeras}Sargeras{/link}. En œuvrant avec Gul'dan, Medivh aida à ouvrir un passage entre les deux mondes.]=],
		},
		{
			title = "Histoire",
			text = [=[Les premiers orcs passèrent en petit nombre et pillèrent le Noir Marécage. Puis le portail s'élargit et la {link:horde}Horde{/link} arriva en force, sous le commandement du chef de guerre Blackhand. Le roi {link:llane-wrynn}Llane Wrynn{/link} et son champion {link:anduin-lothar}Anduin Lothar{/link} les combattirent pendant des années à travers le royaume du sud. La Horde incendia les fermes d'{link:elwynn-forest}Elwynn{/link}, les forêts du {link:duskwood}Bois de la Pénombre{/link} et l'abbaye de {link:northshire-abbey}Northshire{/link}. Lothar et le jeune mage {link:khadgar}Khadgar{/link} finirent par tuer le Gardien devenu fou dans sa tour de {link:karazhan}Karazhan{/link}. Il était trop tard pour le royaume. La demi-orque {link:garona}Garona{/link} tua le roi Llane dans son propre donjon, {link:orgrim-doomhammer}Orgrim Doomhammer{/link} prit la Horde à Blackhand, et {link:stormwind-city}Stormwind{/link} fut mise à sac.]=],
		},
		{
			title = "Importance",
			text = [=[{link:anduin-lothar}Lothar{/link} mena les survivants au nord, par-delà la mer, jusqu'en {link:lordaeron}Lordaeron{/link}, emmenant avec lui {link:varian-wrynn}Varian{/link}, le fils de {link:llane-wrynn}Llane{/link}. Leurs avertissements poussèrent le roi {link:terenas-menethil}Terenas Menethil{/link} à rassembler l'{link:alliance}Alliance{/link} et à se préparer à la {link:second-war}Deuxième Guerre{/link}.]=],
		},
	},
})

Translate("frFR", "second-war", {
	title = "Deuxième Guerre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Deuxième Guerre opposa la {link:horde}Horde{/link} d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link} à l'{link:alliance}Alliance{/link} de {link:lordaeron}Lordaeron{/link}. La Horde marcha vers le nord pour conquérir les royaumes humains qui avaient survécu à la {link:first-war}Première Guerre{/link}. Elle fut brisée au pic {link:blackrock-mountain}Blackrock{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[Le roi {link:terenas-menethil}Terenas Menethil{/link} de {link:lordaeron}Lordaeron{/link} rassembla les royaumes humains en une {link:alliance}Alliance{/link}, avec {link:anduin-lothar}Anduin Lothar{/link} pour commandant. Les nains d'{link:kingdom-of-ironforge}Ironforge{/link} et les gnomes les rejoignirent. Les elfes de {link:quel-thalas}Quel'Thalas{/link} aussi, liés par le vieux serment qu'ils avaient juré à la lignée de {link:thoradin}Thoradin{/link}, car Lothar en était le dernier héritier. La {link:horde}Horde{/link} vint plus puissante qu'auparavant. Doomhammer rallia à lui des ogres et les trolls amani de Zul'jin. Le {link:dragonmaw-clan}clan Dragonmaw{/link} asservit le vol draconique rouge et mena ses dragons au combat. {link:gul-dan}Gul'dan{/link} releva des chevaliers de la mort à partir des cadavres de chevaliers humains tombés. La Horde submergea Khaz Modan et incendia les frontières de Quel'Thalas. Le seigneur Perenolde d'{link:alterac-mountains}Alterac{/link} trahit l'Alliance au profit des orcs. La Horde atteignit les murs de la capitale de Lordaeron elle-même.]=],
		},
		{
			title = "Le tournant de la guerre",
			text = [=[Au plus fort de la guerre, {link:gul-dan}Gul'dan{/link} abandonna Doomhammer. Il fit voile avec ses partisans pour chercher la tombe de {link:sargeras}Sargeras{/link}, et la {link:horde}Horde{/link} dut faire demi-tour pour le châtier. L'{link:alliance}Alliance{/link} saisit l'occasion. Elle repoussa la Horde au sud jusqu'au pic {link:blackrock-mountain}Blackrock{/link}. Là, {link:anduin-lothar}Lothar{/link} tomba sous les coups de Doomhammer. Son lieutenant {link:turalyon}Turalyon{/link} reprit sa bannière et écrasa la Horde dans {link:burning-steppes}les Steppes{/link} ardentes.]=],
		},
		{
			title = "Importance",
			text = [=[Les orcs survivants furent parqués dans des camps d'internement. La {link:dark-portal}Porte des Ténèbres{/link} fut détruite. L'{link:alliance}Alliance{/link} avait gagné, mais sa victoire était coûteuse. Ses royaumes se querellèrent bientôt sur le prix des camps, et {link:gilneas}Gilneas{/link} et {link:stromgarde-keep}Stromgarde{/link} quittèrent l'Alliance.]=],
		},
	},
})

Translate("frFR", "third-war", {
	title = "Troisième Guerre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Troisième Guerre fut la deuxième invasion d'{link:azeroth}Azeroth{/link} par la {link:burning-legion}Légion ardente{/link}. Elle commença en {link:lordaeron}Lordaeron{/link} avec une peste de non-mort et s'acheva en {link:kalimdor}Kalimdor{/link} avec la destruction d'{link:archimonde}Archimonde{/link}. Elle coûta à l'humanité son plus grand royaume et aux elfes de la nuit leur immortalité.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, le démon {link:kil-jaeden}Kil'jaeden{/link} enferma l'esprit du chaman {link:orcs}orc{/link} {link:ner-zhul}Ner'zhul{/link} dans une prison gelée du Norfendre et en fit le roi-liche. Par l'intermédiaire du nécromancien {link:kel-thuzad}Kel'Thuzad{/link} et de son {link:cult-of-the-damned}culte des Damnés{/link}, le roi-liche répandit une peste dans les villages de {link:lordaeron}Lordaeron{/link}. Ses victimes se relevèrent pour former le {link:scourge}Fléau{/link} mort-vivant. Au même moment, le jeune orc {link:thrall}Thrall{/link} libéra son peuple des camps d'internement et forgea une nouvelle {link:horde}Horde{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[Un mystérieux prophète avertit les rois de l'est de fuir à l'ouest par-delà la mer. Le roi {link:terenas-menethil}Terenas Menethil{/link} ne voulut pas l'écouter, mais {link:thrall}Thrall{/link} et {link:jaina-proudmoore}Jaina Proudmoore{/link} entendirent l'appel. Le prophète était {link:medivh}Medivh{/link}, revenu d'entre les morts. En {link:lordaeron}Lordaeron{/link}, le prince {link:arthas-menethil}Arthas Menethil{/link} traqua la peste jusqu'à sa source. Après l'{link:culling-of-stratholme}Épuration de Stratholme{/link}, il fit voile vers le Norfendre et prit l'épée maudite Deuillegivre. Il revint en chevalier de la mort et provoqua la {link:fall-of-lordaeron}chute de Lordaeron{/link}. Le {link:scourge}Fléau{/link} releva {link:kel-thuzad}Kel'Thuzad{/link} au puits de Soleil de {link:quel-thalas}Quel'Thalas{/link}, et {link:archimonde}Archimonde{/link} entra dans le monde à {link:dalaran}Dalaran{/link} et la détruisit. Puis la Légion suivit la {link:horde}Horde{/link} et les humains en {link:kalimdor}Kalimdor{/link}. Là, les elfes de la nuit sortirent de leur veille.]=],
		},
		{
			title = "Importance",
			text = [=[{link:orcs}Orcs{/link}, humains et elfes de la nuit firent enfin cause commune. Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, ils détruisirent {link:archimonde}Archimonde{/link}. De la guerre naquirent les terres de la nouvelle {link:horde}Horde{/link} en {link:kalimdor}Kalimdor{/link}, la {link:theramore-isle}cité de Theramore{/link} et les {link:forsaken}Réprouvés{/link}. Ses blessures sont toujours ouvertes.]=],
		},
	},
})

Translate("frFR", "battle-of-mount-hyjal", {
	title = "Bataille du mont Hyjal",
	aliases = { "Bataille d'Hyjal" },
	sections = {
		{
			title = "Résumé",
			text = [=[La bataille du mont Hyjal fut la dernière bataille de la {link:third-war}Troisième Guerre{/link}. Sur les pentes de la montagne sacrée, orcs, humains et elfes de la nuit firent front ensemble contre la {link:burning-legion}Légion ardente{/link}. Le seigneur démon {link:archimonde}Archimonde{/link} fut détruit aux racines de {link:nordrassil}Nordrassil{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[La Légion était venue en {link:kalimdor}Kalimdor{/link} pour l'Arbre-Monde. {link:archimonde}Archimonde{/link} voulait drainer le pouvoir du second puits d'Éternité qui se trouvait sous ses racines, et ainsi consumer le monde. Le {link:scourge}Fléau{/link} marchait devant lui. Les elfes de la nuit de {link:tyrande-whisperwind}Tyrande Whisperwind{/link} et de {link:malfurion-stormrage}Malfurion Stormrage{/link} ne pouvaient résister seuls. {link:medivh}Medivh{/link} réunit leurs chefs, {link:thrall}Thrall{/link} pour la {link:horde}Horde{/link} et {link:jaina-proudmoore}Jaina Proudmoore{/link} pour les humains. Il leur dit que ce n'était qu'ensemble qu'ils pourraient survivre.]=],
		},
		{
			title = "Histoire",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} conçut le plan. Les humains tinrent sur les pentes inférieures, puis les orcs plus haut, et chacun tint aussi longtemps qu'il le put avant de se replier. Pendant qu'ils combattaient, Malfurion prépara un piège au sommet. {link:archimonde}Archimonde{/link} perça chaque ligne l'une après l'autre et atteignit enfin l'arbre. Tandis qu'il escaladait {link:nordrassil}Nordrassil{/link}, Malfurion sonna le cor de {link:cenarius}Cenarius{/link}. Les esprits des ancêtres des elfes de la nuit, rassemblés en innombrables feux follets, s'abattirent sur le démon. Leur pouvoir, et celui de l'Arbre-Monde, fut libéré en une seule explosion. Archimonde fut détruit.]=],
		},
		{
			title = "Importance",
			text = [=[La victoire sauva le monde, mais elle eut un grand prix. {link:nordrassil}Nordrassil{/link} abandonna son pouvoir, et les elfes de la nuit perdirent l'immortalité qu'il leur avait accordée. L'arbre fut brûlé mais pas tué. La bataille forgea aussi une brève paix entre l'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link}.]=],
		},
	},
})

Translate("frFR", "culling-of-stratholme", {
	title = "Épuration de Stratholme",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Épuration de Stratholme fut le massacre des habitants de Stratholme par les soldats du prince {link:arthas-menethil}Arthas Menethil{/link}. Elle eut lieu pendant la {link:third-war}Troisième Guerre{/link}, quand la peste de la non-mort atteignit la cité. Elle marqua le début de la chute du prince.]=],
		},
		{
			title = "Origines",
			text = [=[{link:arthas-menethil}Arthas{/link} avait traqué la peste à travers {link:lordaeron}Lordaeron{/link} avec l'ensorceleuse {link:jaina-proudmoore}Jaina Proudmoore{/link} et son mentor {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}. Il apprit que le {link:cult-of-the-damned}culte des Damnés{/link} avait contaminé le grain expédié depuis les greniers d'{link:ruins-of-andorhal}Andorhal{/link}. À Stratholme, il découvrit que le grain contaminé avait déjà été distribué. Tous ceux qui en avaient mangé allaient bientôt mourir et se relever parmi le {link:scourge}Fléau{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[{link:arthas-menethil}Arthas{/link} ordonna de purger la cité avant que ses habitants ne se transforment. {link:uther-the-lightbringer}Uther{/link} refusa d'y prendre part, et Arthas lui retira son commandement pour trahison. {link:jaina-proudmoore}Jaina{/link} ne voulut pas regarder, et elle le quitta. Le prince mena les soldats restés loyaux dans Stratholme et passa ses habitants au fil de l'épée, maison après maison. Là où ils n'étaient pas encore arrivés, des citoyens se transformaient déjà. Le seigneur de l'effroi Mal'Ganis attendait dans la cité. Il se moqua du prince et le défia de le suivre au Norfendre. Arthas jura de le traquer.]=],
		},
		{
			title = "Importance",
			text = [=[L'Épuration brisa le lien entre {link:arthas-menethil}Arthas{/link} et ceux qui l'aimaient. Elle l'envoya au nord, vers Deuillegivre et vers la {link:fall-of-lordaeron}chute de Lordaeron{/link}.]=],
		},
		{
			title = "De nos jours",
			text = [=[Stratholme gît en ruine dans les {link:eastern-plaguelands}Maleterres de l'est{/link}. Le {link:scourge}Fléau{/link} tient une grande partie de la cité. La {link:scarlet-crusade}Croisade écarlate{/link} s'accroche au reste, combattant toujours les morts que l'épée d'{link:arthas-menethil}Arthas{/link} n'a pu sauver.]=],
		},
	},
})

Translate("frFR", "fall-of-lordaeron", {
	title = "Chute de Lordaeron",
	sections = {
		{
			title = "Résumé",
			text = [=[La chute de {link:lordaeron}Lordaeron{/link} fut la ruine du plus grand royaume humain par le {link:scourge}Fléau{/link}. Elle survint pendant la {link:third-war}Troisième Guerre{/link}, quand le prince {link:arthas-menethil}Arthas Menethil{/link} revint du Norfendre en serviteur du roi-liche. De tous les royaumes qui avaient mené l'{link:alliance}Alliance{/link}, aucun ne tomba si bas ni si vite.]=],
		},
		{
			title = "Histoire",
			text = [=[Au Norfendre, {link:arthas-menethil}Arthas{/link} prit la lame runique Deuillegivre et tua le seigneur de l'effroi Mal'Ganis. Il perdit son âme au profit de la lame. Il rentra chez lui, et le peuple de la capitale l'accueillit en héros. Il entra dans la salle du trône et tua son père, le roi {link:terenas-menethil}Terenas Menethil{/link}. Le {link:scourge}Fléau{/link} déferla sur le royaume derrière lui. Arthas tua {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} et prit les cendres de l'urne de son père, afin que les restes de {link:kel-thuzad}Kel'Thuzad{/link} puissent y être transportés. Il marcha sur {link:quel-thalas}Quel'Thalas{/link}, abattit ses défenseurs menés par {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, et releva Kel'Thuzad dans les eaux du puits de Soleil. Peu après, le Fléau aida {link:archimonde}Archimonde{/link} à entrer dans le monde à {link:dalaran}Dalaran{/link}.]=],
		},
		{
			title = "Après la chute",
			text = [=[Quand {link:archimonde}Archimonde{/link} fut détruit, les seigneurs de l'effroi cherchèrent à régner eux-mêmes sur le royaume en ruine. {link:arthas-menethil}Arthas{/link} se retourna contre eux avant de répondre à l'appel de son maître dans le nord. {link:sylvanas-windrunner}Sylvanas{/link}, devenue morte-vivante, se libéra de la volonté du roi-liche. Elle et ses {link:forsaken}Réprouvés{/link} abattirent les seigneurs de l'effroi et revendiquèrent les ruines de la capitale.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:lordaeron}Lordaeron{/link} n'est plus. Son cœur est devenu les {link:eastern-plaguelands}Maleterres{/link}, tenues par le {link:scourge}Fléau{/link}. La {link:scarlet-crusade}Croisade écarlate{/link} combat les morts dans les {link:tirisfal-glades}Clairières de Tirisfal{/link} et au-delà. Sous la salle du trône brisée, les {link:forsaken}Réprouvés{/link} ont bâti {link:undercity}Undercity{/link}.]=],
		},
	},
})

Translate("frFR", "dark-portal", {
	title = "Porte des Ténèbres",
	sections = {
		{
			title = "Résumé",
			text = [=[La Porte des Ténèbres est le grand passage entre {link:azeroth}Azeroth{/link} et Draenor, la patrie des orcs. Elle se dresse dans les {link:blasted-lands}Terres foudroyées{/link}, qui étaient jadis les marais du Noir Marécage. Par elle vint la {link:horde}Horde{/link}, et avec elle commença la {link:first-war}Première Guerre{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Le portail fut ouvert par le démoniste {link:gul-dan}Gul'dan{/link} et son {link:shadow-council}Conseil des ombres{/link} depuis Draenor, avec l'aide de {link:medivh}Medivh{/link} sur {link:azeroth}Azeroth{/link}. Medivh était le Gardien de {link:tirisfal-glades}Tirisfal{/link}, mais son esprit était depuis longtemps sous l'emprise de {link:sargeras}Sargeras{/link}, seigneur de la {link:burning-legion}Légion ardente{/link}. Au début, la faille était étroite, et seuls quelques éclaireurs la franchirent. Puis elle fut élargie, et la {link:horde}Horde{/link} tout entière passa dans le marais.]=],
		},
		{
			title = "Histoire",
			text = [=[La {link:horde}Horde{/link} bâtit une grande forteresse autour du portail, qui devint sa route pour les renforts. Quand la {link:second-war}Deuxième Guerre{/link} fut perdue, l'{link:alliance}Alliance{/link} détruisit la Porte des Ténèbres. Quelques années plus tard, le chaman {link:ner-zhul}Ner'zhul{/link} la rouvrit et fit passer une nouvelle Horde pour voler des artefacts de pouvoir. L'Alliance envoya une expédition en Draenor pour éliminer la menace à sa source. Ner'zhul ouvrit des failles vers d'autres mondes, et le portail fut de nouveau détruit. L'expédition ne revint pas. Nul sur {link:azeroth}Azeroth{/link} ne sait ce qu'elle est devenue.]=],
		},
		{
			title = "De nos jours",
			text = [=[La Porte des Ténèbres se dresse, sombre et silencieuse, à l'extrémité sud des {link:blasted-lands}Terres foudroyées{/link}. Les mages et les soldats de {link:nethergarde-keep}Rempart-du-Néant{/link} veillent sur elle. Des démons rôdent encore sur la terre stérile qui l'entoure.]=],
		},
	},
})

Translate("frFR", "well-of-eternity", {
	title = "Puits d'Éternité",
	sections = {
		{
			title = "Résumé",
			text = [=[Le puits d'Éternité était un vaste lac de pouvoir arcanique au cœur du monde ancien. Sur ses rives s'éleva l'empire {link:night-elves}kaldorei{/link}. Sa destruction mit fin à la {link:war-of-the-ancients}guerre des Anciens{/link} et provoqua la {link:great-sundering}Grande Fracture{/link}.]=],
		},
		{
			title = "Nature",
			text = [=[Les histoires les plus anciennes disent que le Puits remplissait une blessure de la terre, laissée par la guerre des titans contre les Dieux très anciens. Ses eaux étaient noires et profondes, et elles contenaient le pouvoir brut du monde lui-même. Les trolls qui s'installèrent près de lui furent changés au fil de nombreuses générations, et ils devinrent les {link:night-elves}elfes de la nuit{/link}. Ils apprirent à manier son pouvoir, et leur maîtrise de la {link:arcane-magic}magie arcanique{/link} fit de leur empire la merveille du monde.]=],
		},
		{
			title = "Histoire",
			text = [=[La reine des elfes de la nuit, {link:queen-azshara}Azshara{/link}, bâtit son palais sur les rives du Puits, et ses Bien-nés y puisèrent toujours plus profondément. Leur magie attira la {link:burning-legion}Légion ardente{/link}. Les Bien-nés tentèrent d'ouvrir un portail pour {link:sargeras}Sargeras{/link} dans le Puits lui-même. Quand le portail fut défait, le Puits s'effondra, et le continent fut déchiré. Là où il se trouvait fait désormais rage le Maelström.]=],
		},
		{
			title = "Son héritage",
			text = [=[Quelque chose du Puits survécut. {link:illidan-stormrage}Illidan Stormrage{/link} en sauva des fioles d'eau et les versa dans un lac du mont Hyjal, créant un second Puits. Là, les Aspects plantèrent {link:nordrassil}Nordrassil{/link}. Les Bien-nés exilés emportèrent une autre fiole à l'est. Avec elle, ils créèrent le puits de Soleil, la source de {link:quel-thalas}Quel'Thalas{/link}. Pendant la {link:third-war}Troisième Guerre{/link}, {link:archimonde}Archimonde{/link} vint en {link:kalimdor}Kalimdor{/link} pour consumer le pouvoir du second Puits, et il échoua.]=],
		},
	},
})

Translate("frFR", "nordrassil", {
	title = "Nordrassil",
	sections = {
		{
			title = "Résumé",
			text = [=[Nordrassil est l'Arbre-Monde, qui s'élève au sommet du mont Hyjal en {link:kalimdor}Kalimdor{/link}. Pendant dix mille ans, il garda le second puits d'Éternité et donna aux {link:night-elves}elfes de la nuit{/link} leur immortalité. Il fut au centre de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:great-sundering}Grande Fracture{/link}, les elfes de la nuit survivants découvrirent qu'{link:illidan-stormrage}Illidan Stormrage{/link} avait créé un nouveau Puits au sommet du mont Hyjal. Les Aspects draconiques vinrent à eux. {link:alexstrasza}Alexstrasza{/link} plaça une graine sacrée dans les eaux du nouveau Puits, et un grand arbre en sortit, ses racines buvant au Puits et le scellant. Nozdormu bénit l'arbre pour que les elfes de la nuit vivent aussi longtemps qu'il se dresserait. Ysera le lia au {link:emerald-dream}Rêve d'émeraude{/link}, afin que les druides puissent parcourir le Rêve à travers lui.]=],
		},
		{
			title = "Histoire",
			text = [=[Sous ses branches, les elfes de la nuit montèrent leur longue veille. Les druides de {link:malfurion-stormrage}Malfurion Stormrage{/link} dormaient à son ombre, leurs esprits errant dans le Rêve. Pendant la {link:third-war}Troisième Guerre{/link}, {link:archimonde}Archimonde{/link} marcha sur l'arbre pour drainer le Puits qui se trouvait dessous. Tandis qu'il escaladait son tronc, Malfurion appela les esprits des ancêtres, et le pouvoir de Nordrassil fut dépensé pour détruire le démon.]=],
		},
		{
			title = "De nos jours",
			text = [=[Nordrassil se dresse toujours, meurtri et affaibli. Les elfes de la nuit ne sont plus immortels. Ils ont planté un nouvel arbre, {link:teldrassil}Teldrassil{/link}, au large de la côte nord, mais il fut cultivé sans la bénédiction des Aspects. Beaucoup des anciens druides doutent qu'il ait jamais dû être planté.]=],
		},
	},
})

Translate("frFR", "holy-light", {
	title = "Lumière sacrée",
	sections = {
		{
			title = "Résumé",
			text = [=[La Lumière sacrée est la puissance de la foi et de la vertu qui répond aux dévots. Ses prêtres guérissent les blessures et réparent les esprits. Ses paladins la portent au combat comme un bouclier et une arme contre les morts-vivants et les démons. La plupart des humains des {link:eastern-kingdoms}Royaumes de l'est{/link} ont été élevés dans sa foi, et de nombreux {link:dwarves}nains{/link} la partagent désormais.]=],
		},
		{
			title = "Nature",
			text = [=[Les fidèles n'enseignent pas que la Lumière est un dieu. Ils enseignent qu'elle demeure en tous ceux qui s'efforcent à la vertu, et qu'elle se renforce par la compassion, le courage et le sacrifice. On ne peut ni la voler ni la plier à la cruauté. Ceux qui tentent de la manier sans foi découvrent qu'elle ne leur répond pas.]=],
		},
		{
			title = "Histoire",
			text = [=[La foi en la Lumière a de profondes racines chez les humains, remontant aux jours d'{link:arathor}Arathor{/link}. Dans le royaume de {link:stormwind-city}Stormwind{/link}, elle était gardée à l'abbaye de {link:northshire-abbey}Northshire{/link} et à la cathédrale de la Lumière. Après la {link:first-war}Première Guerre{/link}, l'archevêque {link:alonsus-faol}Alonsus Faol{/link} vit que la foi seule n'avait pas sauvé le sud. Il unit les clercs de la Lumière aux meilleurs chevaliers de {link:lordaeron}Lordaeron{/link} et fonda l'ordre de la Main d'argent, les premiers paladins. {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} fut le premier d'entre eux. Les paladins combattirent avec honneur pendant la {link:second-war}Deuxième Guerre{/link}. Pendant la {link:third-war}Troisième Guerre{/link}, l'ordre fut déchiré. Le prince {link:arthas-menethil}Arthas Menethil{/link} avait été l'un d'eux.]=],
		},
		{
			title = "De nos jours",
			text = [=[La Lumière est toujours le cœur de la foi de {link:stormwind-city}Stormwind{/link}, et ses prêtres servent dans chaque ville. En {link:lordaeron}Lordaeron{/link}, elle est devenue un cri de guerre. La {link:scarlet-crusade}Croisade écarlate{/link} brûle au nom de la Lumière tous ceux qu'elle soupçonne de porter la peste. L'{link:argent-dawn}Aube d'argent{/link} combat les mêmes morts d'une main plus sûre.]=],
		},
	},
})

Translate("frFR", "arcane-magic", {
	title = "Magie arcanique",
	sections = {
		{
			title = "Résumé",
			text = [=[La magie arcanique est la magie de l'esprit et des motifs du monde. Ses maîtres plient l'espace et le temps, invoquent le feu et le givre, et voient ce que d'autres ne peuvent voir. C'est la plus ancienne magie savante d'{link:azeroth}Azeroth{/link}, et la plus dangereuse pour ceux qui l'aiment trop.]=],
		},
		{
			title = "Nature",
			text = [=[Le pouvoir arcanique peut être appris par ceux qui ont du talent et de la discipline, mais il ne donne rien gratuitement. Ceux qui le manient finissent par en avoir soif. Il appelle aussi les démons de la {link:burning-legion}Légion ardente{/link}, affamés de mondes riches en magie. Chaque grand âge de pouvoir arcanique sur {link:azeroth}Azeroth{/link} a attiré le regard de la Légion.]=],
		},
		{
			title = "Histoire",
			text = [=[Les elfes de la nuit maîtrisèrent les premiers la magie arcanique au {link:well-of-eternity}puits d'Éternité{/link}, et leurs Bien-nés s'en servirent pour provoquer la {link:war-of-the-ancients}guerre des Anciens{/link}. Après la {link:great-sundering}Grande Fracture{/link}, les elfes de la nuit la proscrivirent. Les Bien-nés qui refusèrent d'y renoncer furent exilés. Ils fondèrent {link:quel-thalas}Quel'Thalas{/link} à l'est et devinrent les {link:high-elves}hauts-elfes{/link}. Pendant les {link:troll-wars}guerres des Trolls{/link}, ils enseignèrent la magie à cent humains d'{link:arathor}Arathor{/link}. L'art se répandit dans les terres humaines. Les mages d'Arathor élevèrent la cité de {link:dalaran}Dalaran{/link}, et son conseil dirigeant, le {link:kirin-tor}Kirin Tor{/link}, veillait sur l'usage de la magie. Quand des démons commencèrent à apparaître dans les terres humaines, les elfes et les mages fondèrent {link:shadow-council}le Conseil{/link} secret de {link:tirisfal-glades}Tirisfal{/link}. Ils choisirent un Gardien pour combattre seul la Légion. Les derniers Gardiens furent {link:aegwynn}Aegwynn{/link} et son fils {link:medivh}Medivh{/link}.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:dalaran}Dalaran{/link} fut détruite par {link:archimonde}Archimonde{/link} pendant la {link:third-war}Troisième Guerre{/link}. Ses mages la rebâtissent désormais derrière une barrière violette chatoyante, dans les contreforts d'{link:alterac-mountains}Alterac{/link}. Des mages se forment encore à {link:stormwind-city}Stormwind{/link}, à {link:ironforge}Ironforge{/link} et à {link:theramore-isle}Theramore{/link}. Chez les elfes de la nuit, l'ancienne loi contre la magie arcanique tient toujours.]=],
		},
	},
})

Translate("frFR", "fel-magic", {
	title = "Magie gangrenée",
	sections = {
		{
			title = "Résumé",
			text = [=[La magie gangrenée est la magie de la {link:burning-legion}Légion ardente{/link}. Elle tire son pouvoir de la destruction et du vol de la vie. Elle brûle d'un feu vert maladif, et elle empoisonne la terre et l'âme de ceux qui l'utilisent. Des démonistes marchandent encore avec elle, connaissant le prix.]=],
		},
		{
			title = "Nature",
			text = [=[Le pouvoir gangrené est rapide et fort, et il demande peu d'étude. Il demande plutôt que quelque chose soit consumé : une vie, une âme, la santé de la terre. Ceux qui l'utilisent sont lentement changés, dans leur corps et dans leur cœur. Les lieux où il a souvent servi se flétrissent et pourrissent.]=],
		},
		{
			title = "Histoire",
			text = [=[La magie gangrenée vint pour la première fois sur {link:azeroth}Azeroth{/link} avec la Légion pendant la {link:war-of-the-ancients}guerre des Anciens{/link}. Beaucoup de Bien-nés qui servaient les démons furent déformés en {link:satyrs}satyres{/link}. Dix mille ans plus tard, elle revint par les {link:orcs}orcs{/link}. Sur Draenor, le seigneur démon {link:kil-jaeden}Kil'jaeden{/link} enseigna ses secrets à {link:gul-dan}Gul'dan{/link} et à ses démonistes. Les chefs orcs burent le sang du démon {link:mannoroth}Mannoroth{/link}, qui les emplit d'une rage terrible. La terre de Draenor mourut sous leur magie. Les orcs portèrent la malédiction à travers la {link:dark-portal}Porte des Ténèbres{/link} jusque dans la {link:first-war}Première Guerre{/link} et la {link:second-war}Deuxième Guerre{/link}. Pendant la {link:third-war}Troisième Guerre{/link}, {link:grom-hellscream}Grom Hellscream{/link} tua Mannoroth et libéra son peuple du sang du démon au prix de sa propre vie. {link:illidan-stormrage}Illidan Stormrage{/link} consuma le {link:skull-of-gul-dan}crâne de Gul'dan{/link} et prit le pouvoir d'un démon.]=],
		},
		{
			title = "De nos jours",
			text = [=[Les forêts de {link:felwood}Gangrebois{/link} portent encore la souillure de la Légion. Les démonistes de la {link:burning-blade}Lame ardente{/link} servent des démons dans l'ombre d'{link:orgrimmar}Orgrimmar{/link} et de {link:durotar}Durotar{/link}. Les satyres hantent {link:ashenvale}Orneval{/link}. Les démonistes de l'{link:alliance}Alliance{/link} et de la {link:horde}Horde{/link} étudient encore cet art. Ils affirment en être les maîtres.]=],
		},
	},
})

Translate("frFR", "emerald-dream", {
	title = "Rêve d'émeraude",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rêve d'émeraude est un vaste royaume spirituel qui reflète le monde. Il montre {link:azeroth}Azeroth{/link} tel qu'il aurait pu être, sauvage et intact de toute main mortelle. Sa gardienne est Ysera, l'Aspect du vol draconique vert. Les druides des {link:night-elves}elfes de la nuit{/link} le parcourent en esprit pendant que leur corps dort.]=],
		},
		{
			title = "Nature",
			text = [=[Les chroniques tiennent que les titans façonnèrent le Rêve comme une image vivante de leur dessein pour le monde. C'est le royaume de la croissance et des rêves. Les dragons verts gardent ses portes, et les esprits des terres sauvages y demeurent. Le temps et la distance n'y suivent pas les règles du monde éveillé.]=],
		},
		{
			title = "Histoire",
			text = [=[Le demi-dieu {link:cenarius}Cenarius{/link} enseigna à {link:malfurion-stormrage}Malfurion Stormrage{/link} les voies du druidisme, et par elles Malfurion apprit à entrer dans le Rêve. Après la {link:war-of-the-ancients}guerre des Anciens{/link}, Ysera lia {link:nordrassil}Nordrassil{/link} au Rêve. Pendant des milliers d'années, les druides du {link:cenarion-circle}Cercle cénarien{/link} dormirent dans des refuges cachés, leurs esprits errant dans le Rêve tandis que les {link:sentinels}Sentinelles{/link} gardaient leurs corps. Ils furent réveillés pour combattre pendant la {link:third-war}Troisième Guerre{/link}. Après la victoire, les druides reprirent leur œuvre.]=],
		},
		{
			title = "De nos jours",
			text = [=[{link:malfurion-stormrage}Malfurion{/link} est reparti dans le Rêve, et il n'est pas revenu. {link:fandral-staghelm}Fandral Staghelm{/link} dirige les druides en son absence. Quelque chose ne va pas dans le Rêve. Des dragons verts sont aperçus dans le monde éveillé, et certains d'entre eux ne sont plus ce qu'ils étaient. Les druides de {link:moonglade}Reflet-de-Lune{/link} parlent d'une obscurité qui se répand dans le Rêve, et que nul ne sait encore nommer.]=],
		},
	},
})

Translate("frFR", "elements", {
	title = "Éléments",
	sections = {
		{
			title = "Résumé",
			text = [=[Les éléments sont les forces vivantes de la terre, du feu, de l'eau et de l'air. Sous leurs formes brutes, ils sont sauvages et destructeurs. En équilibre, ils soutiennent le monde. Les chamans des {link:orcs}orcs{/link}, des {link:tauren}taurens{/link} et des {link:trolls}trolls{/link} parlent avec les esprits des éléments et leur demandent leur aide.]=],
		},
		{
			title = "Nature",
			text = [=[Quatre grands seigneurs élémentaires règnent sur les éléments. Ragnaros est le seigneur du feu. Therazane est la mère de la pierre. {link:al-akir}Al'Akir{/link} est le seigneur des vents, dont le royaume est {link:skywall}Skywall{/link}. Neptulon est le seigneur des marées. Leurs serviteurs sont sauvages et hostiles à la vie mortelle. Les esprits mineurs, en revanche, peuvent entendre raison. Un chaman ne les commande pas. Un chaman demande, et les esprits choisissent de répondre ou non.]=],
		},
		{
			title = "Histoire",
			text = [=[Au premier âge du monde, les seigneurs élémentaires combattirent pour les Dieux très anciens. Les titans les vainquirent et les enfermèrent dans un royaume séparé du monde. Sur Draenor, les orcs étaient un peuple de chamans. Quand {link:gul-dan}Gul'dan{/link} les tourna vers la magie démoniaque, les esprits les abandonnèrent. Bien plus tard, à Khaz Modan, le thane sombrefer {link:ruins-of-thaurissan}Thaurissan{/link} invoqua Ragnaros dans le monde. L'invocation tua le thane et fit surgir {link:blackrock-mountain}le mont Blackrock{/link}. Ragnaros demeure sous lui depuis. Après la {link:second-war}Deuxième Guerre{/link}, le vieux chaman {link:drek-thar}Drek'Thar{/link} enseigna les voies des esprits au jeune {link:thrall}Thrall{/link}. Les éléments répondirent à la nouvelle {link:horde}Horde{/link} comme ils n'avaient pas répondu à l'ancienne.]=],
		},
		{
			title = "De nos jours",
			text = [=[Ragnaros gouverne les nains {link:dark-iron-dwarves}Sombrefer{/link} depuis les profondeurs en fusion du mont {link:blackrock-mountain}Blackrock{/link}. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} cherche à éveiller les éléments pour ses propres fins. Les chamans de la {link:horde}Horde{/link} maintiennent l'ancien équilibre, comme leurs ancêtres le faisaient avant la venue des démons.]=],
		},
	},
})
